BOOL sub_02006B84(void) {
    u16 *fanfareDelay = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_FANFARE_DELAY);

    if (GF_SndPlayerCountPlayingSeqByPlayerNo(2) != 0) {
        return 1;
    }

    if (*fanfareDelay > 0) {
        (*fanfareDelay)--;
        return 1;
    }

    return 0;
}

void sub_02006BB0(int frames) {
    NNS_SndPlayerStopSeq(GF_GetSoundHandle(SOUND_HANDLE_TYPE_FANFARE), frames);
    GF_Snd_LoadState(sub_02005328(SOUND_HEAP_STATE_FANFARE));
}
